// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzzed params: from address, array length seed, value v
    function testFuzz_property(address from, uint256 seedLen, uint256 v) public {
        // keep array length reasonable but allow >0
        uint256 len = bound(seedLen, 1, 8);

        // prepare tos array
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // use distinct addresses derived from from and i to keep fuzz space wide
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i, v)))));
        }

        // Deploy a callee that can be toggled to revert or succeed.
        // We will pass its address as caddress to C.transfer.
        ToggleReverter callee = new ToggleReverter();

        // Ensure callee will revert when called: toggle to revert = true
        callee.setShouldRevert(true);

        // Call transfer on c via try/catch to capture return without reverting test
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // transfer is not expected to revert in either implementation for this contract
            ok = false;
        }

        // GENERAL RULE (single assertion): Reference C always returns true for any non-empty tos
        // (it ignores failures from the external call). The mutant will return false when the callee fails.
        assertTrue(ok);
    }
}

// Adversarial helper: exposes the exact function signature that C encodes via selector
// function transferFrom(address from,address to,uint256 v)
contract ToggleReverter {
    bool public shouldRevert;
    // record last call for potential inspection (not used in assertion here, but minimal recording)
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    function setShouldRevert(bool b) external {
        shouldRevert = b;
    }

    // match selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastV = v;
        if (shouldRevert) revert("revert as instructed");
        return true;
    }

    // fallback to be safe
    fallback() external payable {
        if (shouldRevert) revert("revert fallback");
    }
    receive() external payable {}
}
